import test from 'node:test';import assert from 'node:assert/strict';
import {ambienceForScene,createSoundscape,AMBIENCE_VOLUME_KEY} from '../soundscape.js';
const turn=()=>new Promise(resolve=>queueMicrotask(resolve));
function harness(outcomes=[],options={}){const audios=[],requests=[],intervals=new Map(),data=new Map();let timer=0;const storage={getItem:k=>data.get(k)??null,setItem:(k,v)=>data.set(k,v)};
 const scape=createSoundscape({storage,resolve:id=>'/ambience/'+id+'.mp3',createAudio(){let volume=1;const a={paused:true,volumeWrites:0,preload:'',plays:0,pauses:0,src:'',pause(){this.pauses++;this.paused=true;},play(){this.plays++;this.paused=false;requests.push(this.src);const result=outcomes.shift();if(result instanceof Error)return Promise.reject(result);if(result)return result;this.paused=false;return Promise.resolve();},removeAttribute(){this.src='';},load(){},remove(){}};Object.defineProperty(a,'volume',{get:()=>volume,set:value=>{volume=value;a.volumeWrites++;}});audios.push(a);return a;},setInterval(fn){const id=++timer;intervals.set(id,fn);return id;},clearInterval:id=>intervals.delete(id),...options});
 return {scape,audios,requests,storage,data,settle(){for(let n=0;n<100;n++)for(const fn of [...intervals.values()])fn();},intervals};}
const town={key:'town'},workshop={key:'workshop',household:{kind:'workshop'}},field={mode:'field'};
test('soundscape maps occupied workrooms and explicit outdoor places without birds in interiors or unmatched origins',()=>{assert.equal(ambienceForScene(town),'town');assert.equal(ambienceForScene(workshop),'workshop');assert.equal(ambienceForScene({key:'east',chapter:5,household:{kind:'archive'}}),null);assert.equal(ambienceForScene({key:'sanctuary',household:{kind:'garden'}}),null);assert.equal(ambienceForScene({key:'forest'}),'garden');assert.equal(ambienceForScene({biome:{id:'crystal'}}),null);assert.equal(ambienceForScene({biome:{id:'coral'}}),'water');for(const originId of ['brass-rail','mira-archive','veyr-storm'])assert.equal(ambienceForScene({originId,key:'town'}),null);assert.equal(ambienceForScene({originId:'sable-reed',originIndoor:true}),null);assert.equal(ambienceForScene({originId:'riven-tide'}),'water');});
test('construction and inactive/unmapped scenes never create audio or download beds',async()=>{const h=harness();assert.equal(h.audios.length,0);h.scape.sync({scene:town,state:field,active:false});h.scape.sync({scene:{key:'home'},state:field,active:true});await turn();assert.equal(h.audios.length,0);assert.equal(h.requests.length,0);});
test('active sound starts lazily at independent .24 volume, ducks during dialogue, and repeated frames reuse it',async()=>{const h=harness();for(let n=0;n<50;n++)h.scape.sync({scene:town,state:field,active:true});await turn();h.settle();assert.equal(h.requests.length,1);assert.equal(h.audios.length,2);assert.equal(h.audios[0].loop,true);assert.equal(h.audios[0].preload,'none');assert.equal(h.audios[0].volume,.24);h.scape.sync({scene:town,state:{mode:'dialog'},active:true,ducked:true});h.settle();assert.ok(Math.abs(h.audios[0].volume-.072)<1e-8);assert.equal(h.requests.length,1);h.scape.sync({scene:town,state:field,active:true});h.settle();assert.equal(h.audios[0].volume,.24);});
test('settled and inactive animation frames perform no redundant media writes or pause calls',async()=>{
 const h=harness(),counts=()=>h.audios.map(a=>[a.volumeWrites,a.pauses,a.plays]);
 h.scape.sync({scene:town,state:field,active:true});await turn();h.settle();
 let before=counts();for(let n=0;n<60;n++)h.scape.sync({scene:town,state:field,active:true});
 assert.deepEqual(counts(),before,'steady playback is driven by its current deck, not the frame loop');
 h.scape.sync({scene:town,state:{mode:'dialog'},active:true,ducked:true});h.settle();assert.equal(h.audios[0].volume,.072);
 before=counts();for(let n=0;n<60;n++)h.scape.sync({scene:town,state:{mode:'dialog'},active:true,ducked:true});
 assert.deepEqual(counts(),before,'settled ducking also leaves media alone');
 h.scape.sync({scene:town,state:field,active:false});assert.ok(h.audios.every(a=>a.paused&&a.volume===0));
 before=counts();for(let n=0;n<60;n++)h.scape.sync({scene:town,state:field,active:false});
 assert.deepEqual(counts(),before,'already paused decks are not paused again each frame');
 h.scape.sync({scene:town,state:field,active:true});await turn();h.settle();assert.equal(h.scape.state.playing,true);assert.equal(h.audios[0].volume,.24);
});
test('pausing, hidden/menu gate, battles and unmapped rooms stop every deck immediately',async()=>{for(const gate of [{active:false,state:field},{active:true,state:{mode:'battle'}},{active:true,state:{mode:'observatory'}},{active:true,state:field,scene:{key:'home'}}]){const h=harness();h.scape.sync({scene:town,state:field,active:true});await turn();h.settle();h.scape.sync({scene:town,...gate});assert.equal(h.scape.state.playing,false);assert.ok(h.audios.every(a=>a.paused&&a.volume===0));assert.equal(h.intervals.size,0);}});
test('volume zero persists as mute and resumes only after an explicit nonzero setting',async()=>{const h=harness();h.scape.setVolume(0);h.scape.sync({scene:town,state:field,active:true});assert.equal(h.requests.length,0);assert.equal(h.data.get(AMBIENCE_VOLUME_KEY),'0');h.scape.setVolume(.4);await turn();h.settle();assert.equal(h.audios[0].volume,.4);h.scape.setVolume(0);assert.ok(h.audios.every(a=>a.paused));});
test('blocked autoplay never retries on frames, then an explicit gesture retries successfully',async()=>{const blocked=Object.assign(Error('blocked'),{name:'NotAllowedError'}),h=harness([blocked]);h.scape.sync({scene:town,state:field,active:true});await turn();assert.equal(h.scape.state.blocked,true);for(let n=0;n<100;n++)h.scape.sync({scene:town,state:field,active:true});assert.equal(h.requests.length,1);h.scape.unlock();await turn();h.settle();assert.equal(h.requests.length,2);assert.equal(h.scape.state.playing,true);assert.equal(h.scape.state.blocked,false);});
test('download failures remain optional and do not retry until a new scene bed or gesture',async()=>{const h=harness([Error('404')]);h.scape.sync({scene:town,state:field,active:true});await turn();for(let n=0;n<10;n++)h.scape.sync({scene:town,state:field,active:true});assert.equal(h.requests.length,1);assert.equal(h.scape.state.playing,false);h.scape.sync({scene:workshop,state:field,active:true});await turn();h.settle();assert.deepEqual(h.requests,['/ambience/town.mp3','/ambience/workshop.mp3']);assert.equal(h.scape.state.playing,true);});
test('late play completion after pausing cannot restart a stopped bed',async()=>{let resolve;const pending=new Promise(r=>resolve=r),h=harness([pending]);h.scape.sync({scene:town,state:field,active:true});h.scape.sync({scene:town,state:field,active:false});resolve();await turn();assert.equal(h.scape.state.playing,false);assert.ok(h.audios.every(a=>a.paused&&a.volume===0));});
test('rapid bed changes cancel obsolete requests and destroy releases bounded decks and timers',async()=>{let resolve;const pending=new Promise(r=>resolve=r),h=harness([pending]);h.scape.sync({scene:town,state:field,active:true});h.scape.sync({scene:workshop,state:field,active:true});await turn();resolve();await turn();h.settle();assert.equal(h.audios.length,2);assert.equal(h.scape.state.profile,'workshop');assert.equal(h.scape.state.playing,true);assert.equal(h.audios.filter(a=>a.volume===.24).length,1);h.scape.destroy();h.scape.sync({scene:town,state:field,active:true});h.scape.unlock();assert.equal(h.requests.length,2);assert.equal(h.intervals.size,0);assert.ok(h.audios.every(a=>a.paused&&a.src===''));});
test('denied storage or missing HTMLAudio cannot interrupt the game',()=>{const s=createSoundscape({storage:{getItem(){throw Error();},setItem(){throw Error();}},createAudio(){throw Error();}});assert.equal(s.state.volume,.24);assert.doesNotThrow(()=>s.sync({scene:town,state:field,active:true}));assert.doesNotThrow(()=>s.setVolume(.2));s.destroy();});

test('changing places crossfades a bounded pair of decks instead of cutting the old bed',async()=>{const h=harness();h.scape.sync({scene:town,state:field,active:true});await turn();h.settle();const first=h.audios[0];h.scape.sync({scene:workshop,state:field,active:true});assert.equal(first.paused,false);assert.ok(first.volume>0&&first.volume<.24);await turn();assert.equal(h.audios[1].paused,false);h.settle();assert.equal(first.paused,true);assert.equal(first.volume,0);assert.equal(h.audios[1].volume,.24);assert.equal(h.audios.length,2);});
test('a hung optional download times out once and can retry after a later gesture',async()=>{let expire,cleared=0;const pending=new Promise(()=>{}),h=harness([pending],{setTimeout(fn){expire=fn;return 7;},clearTimeout(){cleared++;}});h.scape.sync({scene:town,state:field,active:true});assert.equal(h.scape.state.pending,true);expire();assert.equal(h.scape.state.pending,false);assert.equal(h.scape.state.playing,false);assert.match(h.scape.state.error,/unavailable/);for(let n=0;n<50;n++)h.scape.sync({scene:town,state:field,active:true});assert.equal(h.requests.length,1);h.scape.unlock();await turn();h.settle();assert.equal(h.requests.length,2);assert.equal(h.scape.state.playing,true);assert.ok(cleared>0);});
test('stored mute and finite volume preferences are respected without opening a media element',()=>{for(const [stored,want]of [['0',0],['.5',.5],['9',1],['bad',.24]]){const scape=createSoundscape({storage:{getItem:()=>stored},createAudio(){assert.fail('eager audio');}});assert.equal(scape.state.volume,want);scape.destroy();}});

test('fading the previous place cannot pause an incoming bed whose play promise is still loading',async()=>{let resolve;const pending=new Promise(r=>resolve=r),h=harness([undefined,undefined,pending]);h.scape.sync({scene:town,state:field,active:true});await turn();h.settle();h.scape.sync({scene:workshop,state:field,active:true});await turn();h.settle();h.scape.sync({scene:{key:'river'},state:field,active:true});const incoming=h.audios.find(a=>a.src==='/ambience/water.mp3'),pauses=incoming.pauses;assert.equal(incoming.paused,false);assert.equal(h.scape.state.pending,true);h.settle();assert.equal(incoming.pauses,pauses,'the fade worker must leave the loading deck alone');assert.equal(incoming.paused,false);assert.equal(incoming.volume,0);resolve();await turn();h.settle();assert.equal(h.scape.state.profile,'water');assert.equal(h.scape.state.playing,true);assert.equal(h.scape.state.pending,false);assert.equal(incoming.volume,.24);h.scape.destroy();});
